use crate::{CallSite, CallSiteField, CatalogField, EventCallSites, FieldWrite};

const fn catalog_field(name: &'static str, id: u32) -> CatalogField {
    CatalogField { name, id }
}
const fn written_field(name: &'static str, write: FieldWrite) -> CallSiteField {
    CallSiteField { name, write }
}
const fn site(module: &'static str, partial: bool, fields: &'static [CallSiteField]) -> CallSite {
    CallSite {
        module,
        partial,
        fields,
    }
}
const fn event(
    event: &'static str,
    code: u32,
    fields: &'static [CatalogField],
    sites: &'static [CallSite],
) -> EventCallSites {
    EventCallSites {
        event,
        code,
        fields,
        sites,
    }
}

